const PLACEHOLDER_JPEG_BASE64 =
  "";

export const dynamic = "force-static";

export function GET() {
  return new Response(Buffer.from(PLACEHOLDER_JPEG_BASE64, "base64"), {
    headers: {
      "Cache-Control": "public, max-age=31536000, immutable",
      "Content-Type": "image/jpeg",
    },
  });
}
